using System.Text;

namespace Macaron.DependencyInjection.Generator;

internal static class CreationRenderer
{
    internal static string Render(CreationDefinition definition)
    {
        var factory = definition.Factory;
        var source = new StringBuilder();

        source.AppendLine(
            """
            // <auto-generated />
            #nullable enable

            namespace Macaron.DependencyInjection
            {
                internal static partial class InjectionContextExtensions
                {
            """
        );
        source.AppendLine($"        internal static {factory.TypeName} Create(");

        var parameters = definition.Parameters.Length == 0 ? "" : $", {definition.Parameters}";

        source.AppendLine($"            this global::Macaron.DependencyInjection.InjectionContext<{factory.TypeName}> {definition.ContextName}{parameters})");
        source.AppendLine("        {");
        source.AppendLine($"            var {definition.ResolverName} = {definition.ContextName}.Resolver;");

        if (factory.DependencyStatements.Length > 0)
        {
            foreach (var statement in factory.DependencyStatements.Split('\n'))
            {
                source.AppendLine($"            {statement}");
            }
        }

        source.AppendLine($"            return {factory.CreationExpression};");
        source.AppendLine("        }");
        source.AppendLine("    }");
        source.AppendLine("}");

        return source.ToString();
    }
}
